"""Local paired-video review, no server required."""
from pathlib import Path
import json,sys,html
p=Path(sys.argv[1]);cards=[]
for n in range(14,20):
 name=f'arena-g1-{n:03d}';a=json.loads((p/name/'audit.json').read_text());ok=a['task_success'];status='到达 / 停稳复核通过' if ok else '停稳复核未通过（保留原记录）';dist=a.get('final_distance_m',a.get('final_goal_distance_m',0))*100
 cards.append(f'''<section id="e{n}"><h2>第 {n} 轮 <span class="{'ok' if ok else 'warn'}">{status}</span></h2><p>终点误差 {dist:.1f} cm · {a['frames']} 帧 · 30 fps · 完整碰撞安全验收尚未完成</p><div class="pair"><figure><video preload="metadata" playsinline src="{name}/ego.mp4"></video><figcaption>第一人称 · 原始 RGB · 640×480</figcaption></figure><figure><video preload="metadata" playsinline src="{name}/third-person.mp4"></video><figcaption>第三人称 · 根节点＋43 个关节回放 · 960×540</figcaption></figure></div><div class="controls"><button class="play">同步播放</button><button class="reset">回到开头</button><input class="seek" aria-label="时间轴" type="range" min="0" max="{a['frames']/30}" step="0.033333"><output>0.00 s</output></div><p><a href="{name}/ego.mp4">第一人称 MP4</a> · <a href="{name}/third-person.mp4">第三人称 MP4</a></p></section>''')
page='''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>G1 导航 · 双视角回放</title><style>body{background:#10151c;color:#e4eaf2;font:16px/1.6 system-ui;margin:0}main{max-width:1280px;margin:auto;padding:32px 24px}h1{margin-bottom:8px}p,figcaption{color:#aab8c9}section{background:#19222e;border-radius:14px;padding:24px;margin:24px 0}h2{font-size:22px}h2 span{font-size:14px;margin-left:16px}.ok{color:#70d4ab}.warn{color:#ffbc69}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}video{width:100%;aspect-ratio:16/9;background:#000}button{background:#2c4668;border:0;color:white;border-radius:7px;padding:10px 14px;cursor:pointer}.controls{display:flex;align-items:center;gap:12px;margin-top:16px}.seek{flex:1}a{color:#91bdff}nav{display:flex;gap:18px;flex-wrap:wrap}output{min-width:65px}@media(max-width:700px){.pair{grid-template-columns:1fr}.controls{flex-wrap:wrap}}</style><main><h1>G1 导航：第一人称 × 第三人称</h1><p>第 14–19 轮，共六组。两路使用相同帧序号与 30 fps 时间轴，可同步播放。</p><p>第一人称来自实际仿真录制；第三人称按 USD 关节定义和记录状态做运动学回放，未重新执行物理仿真。第 20 轮启动检查失败，没有可播放轨迹。</p><nav>NAV</nav>CARDS</main><script>document.querySelectorAll('section').forEach(s=>{let [a,b]=s.querySelectorAll('video'),seek=s.querySelector('.seek'),out=s.querySelector('output'),btn=s.querySelector('.play');btn.onclick=async()=>{if(!a.paused){a.pause();b.pause();btn.textContent='同步播放';return}b.currentTime=a.currentTime;await Promise.all([a.play(),b.play()]);btn.textContent='暂停'};s.querySelector('.reset').onclick=()=>{a.pause();b.pause();a.currentTime=b.currentTime=0;btn.textContent='同步播放'};seek.oninput=()=>{a.currentTime=b.currentTime=+seek.value;out.textContent=(+seek.value).toFixed(2)+' s'};a.ontimeupdate=()=>{seek.value=a.currentTime;out.textContent=a.currentTime.toFixed(2)+' s';if(!a.paused&&Math.abs(a.currentTime-b.currentTime)>.10)b.currentTime=a.currentTime};a.onended=()=>{b.pause();btn.textContent='同步播放'}});</script></html>'''.replace('CARDS',''.join(cards)).replace('NAV',''.join(f'<a href="#e{n}">第 {n} 轮</a>' for n in range(14,20)))
(p/'index.html').write_text(page)
